/**
 * A deployed file answers the same on every self-hosting entry. The Bun entry (and `nifra dev`) serve
 * it through @nifrajs/web's `servePublicDir`; the Node entry through @nifrajs/node's own reader, so
 * pages keep the node-direct lane. For one tree and one request matrix both entries, generated by the
 * build, give the same status, type, caching, length, range and body, and neither reaches a file
 * outside the tree, a hidden one inside it, or the server bundle beside the client files.
 */
import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { server } from "@nifrajs/core"
import { type NodeServer, serve } from "@nifrajs/node"
import { servePublicDir } from "@nifrajs/web"
import { generateServerEntry } from "../../../packages/web/src/build.ts"

const PUBLIC_FILES = ["/robots.txt", "/logo.SVG", "/.well-known/acme-challenge/token"]
const HASHED_FILES = ["/assets/page-1a2b3c.js", "/assets/big-9f8e7d.bin"]
const BIG = 256 * 1024 + 7
const APP = "answered by the app"

let root = ""
let dir = ""
let node: NodeServer | undefined
let nodeBase = ""
let bunServer: ReturnType<typeof Bun.serve> | undefined
let bunBase = ""

const transpiler = new Bun.Transpiler({ loader: "ts" })
// biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: an async function's constructor is AsyncFunction, which TS does not name.
const AsyncFunction = (async () => {}).constructor as new (
  ...source: string[]
) => (...args: unknown[]) => Promise<unknown>

/** Run a generated entry's code from its static section on, with its folder at `dir`. */
function evaluateEntry(src: string, end: string, tail: string, names: string[], values: unknown[]) {
  const section = src
    .slice(src.indexOf("const STATIC_ROOT"), end === "" ? undefined : src.indexOf(end))
    .replace('new URL("./", import.meta.url)', "ROOT_URL")
    .replace('new URL("./assets/", import.meta.url)', 'new URL("./assets/", ROOT_URL)')
  return new AsyncFunction(
    "ROOT_URL",
    "fileURLToPath",
    ...names,
    `${transpiler.transformSync(section.replace("await serve(app,", "return capture("))}${tail}`,
  )(pathToFileURL(`${dir}/`), fileURLToPath, ...values)
}

beforeAll(async () => {
  root = mkdtempSync(join(tmpdir(), "nifra-static-parity-"))
  dir = join(root, "deploy")
  mkdirSync(join(dir, "assets/.cache"), { recursive: true })
  mkdirSync(join(dir, ".well-known/acme-challenge"), { recursive: true })
  writeFileSync(join(dir, "server.js"), "// the server bundle")
  writeFileSync(join(dir, "robots.txt"), "User-agent: *")
  writeFileSync(join(dir, "logo.SVG"), "<svg/>")
  writeFileSync(join(dir, ".well-known/acme-challenge/token"), "token")
  writeFileSync(join(dir, "assets/page-1a2b3c.js"), "x".repeat(100))
  writeFileSync(join(dir, "assets/big-9f8e7d.bin"), Buffer.alloc(BIG, 1))
  writeFileSync(join(dir, "assets/manifest.json"), "{}")
  writeFileSync(join(dir, "assets/guide.pdf"), "%PDF")
  writeFileSync(join(dir, "assets/theme.css"), "body{}")
  symlinkSync(join(dir, "assets/theme.css"), join(dir, "assets/alias.js"))
  writeFileSync(join(dir, "assets/.cache/x.js"), "cached")
  writeFileSync(join(dir, ".env"), "SECRET=1")
  writeFileSync(join(root, "outside.txt"), "outside")
  symlinkSync(join(root, "outside.txt"), join(dir, "assets/leak.js"))
  symlinkSync(join(dir, ".env"), join(dir, "assets/env.js"))

  const entry = (target: "bun" | "node") =>
    generateServerEntry({
      target,
      adapterImport: "../framework.ts",
      publicFiles: PUBLIC_FILES,
      hashedFiles: HASHED_FILES,
    })
  // biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: the evaluated section declares both functions it returns.
  const bun = (await evaluateEntry(
    entry("bun"),
    "const server = Bun.serve",
    "; return { staticPath, staticResponse }",
    ["servePublicDir"],
    [servePublicDir],
  )) as {
    staticPath(pathname: string): string | undefined
    staticResponse(request: Request): Promise<Response>
  }
  // The entry's own routing: a static path goes to its handler, anything else to the app.
  bunServer = Bun.serve({
    hostname: "127.0.0.1",
    port: 0,
    fetch: (request) =>
      bun.staticPath(new URL(request.url).pathname) === undefined
        ? new Response(APP)
        : bun.staticResponse(request),
  })
  bunBase = `http://127.0.0.1:${bunServer.port}`

  // biome-ignore lint/plugin/requireSafetyCommentForTypeAssertion: the evaluated section returns the options it passed to the capture stub.
  const options = (await evaluateEntry(
    entry("node"),
    "",
    "",
    ["capture"],
    [(captured: unknown) => captured],
  )) as Parameters<typeof serve>[1]
  node = await serve(
    server().get("/*", (c) => c.text(APP)),
    { ...options, hostname: "127.0.0.1", port: 0 },
  )
  nodeBase = `http://127.0.0.1:${node.port}`
})

afterAll(async () => {
  await node?.stop({ drainMs: 0 })
  await bunServer?.stop(true)
  rmSync(root, { recursive: true, force: true })
})

const COMPARED = [
  "content-type",
  "cache-control",
  "content-length",
  "content-range",
  "accept-ranges",
  "x-content-type-options",
]

interface Answer {
  readonly status: number
  readonly headers: Record<string, string | null>
  readonly body: string
}

async function read(res: Response): Promise<Answer> {
  const headers: Record<string, string | null> = {}
  for (const name of COMPARED) headers[name] = res.headers.get(name)
  return { status: res.status, headers, body: await res.text() }
}

const FUTURE = "Wed, 01 Jan 2031 00:00:00 GMT"
const CASES: readonly (readonly [string, string, RequestInit?])[] = [
  ["public file", "/robots.txt"],
  ["upper-case extension", "/logo.SVG"],
  [".well-known", "/.well-known/acme-challenge/token"],
  ["hashed asset", "/assets/page-1a2b3c.js"],
  ["unhashed asset", "/assets/manifest.json"],
  ["pdf", "/assets/guide.pdf"],
  ["a link is typed by its target", "/assets/alias.js"],
  ["HEAD", "/assets/page-1a2b3c.js", { method: "HEAD" }],
  ["range", "/assets/page-1a2b3c.js", { headers: { range: "bytes=0-9" } }],
  ["suffix range", "/assets/big-9f8e7d.bin", { headers: { range: "bytes=-5" } }],
  ["unsatisfiable range", "/assets/page-1a2b3c.js", { headers: { range: "bytes=500-" } }],
  [
    "multi-range is the whole file",
    "/assets/page-1a2b3c.js",
    { headers: { range: "bytes=0-1,4-5" } },
  ],
  // Every entry parses Range with @nifrajs/core/range; each case below once had a second answer.
  ["malformed range", "/assets/page-1a2b3c.js", { headers: { range: "bytes=1-x" } }],
  ["another unit", "/assets/page-1a2b3c.js", { headers: { range: "items=0-9" } }],
  ["inverted range", "/assets/page-1a2b3c.js", { headers: { range: "bytes=9-0" } }],
  ["spaced, upper-case unit", "/assets/page-1a2b3c.js", { headers: { range: "Bytes = 2-4" } }],
  ["overlapping ranges", "/assets/page-1a2b3c.js", { headers: { range: "bytes=0-5,3-9" } }],
  ["adjacent ranges", "/assets/page-1a2b3c.js", { headers: { range: "bytes=5-9,0-4" } }],
  [
    "one satisfiable range among unsatisfiable ones",
    "/assets/page-1a2b3c.js",
    { headers: { range: "bytes=500-,0-1" } },
  ],
  [
    "too many ranges",
    "/assets/page-1a2b3c.js",
    { headers: { range: `bytes=${Array.from({ length: 17 }, (_, i) => `${i}-${i}`).join(",")}` } },
  ],
  ["zero suffix", "/assets/page-1a2b3c.js", { headers: { range: "bytes=-0" } }],
  ["suffix past the start", "/assets/page-1a2b3c.js", { headers: { range: "bytes=-500" } }],
  ["suffix and a range", "/assets/page-1a2b3c.js", { headers: { range: "bytes=-3,0-1" } }],
]

describe("static-file parity: Bun entry (servePublicDir) and Node entry (@nifrajs/node reader)", () => {
  for (const [name, path, init] of CASES) {
    test(name, async () => {
      const bun = await read(await fetch(bunBase + path, init))
      const nodeAnswer = await read(await fetch(nodeBase + path, init))
      // Answered from disk, not refused: the refusals have their own test below.
      expect(bun.status).not.toBe(404)
      expect(nodeAnswer).toEqual(bun)
    })
  }

  test("a file the Node entry streams declares its length on both, whole and ranged", async () => {
    for (const [init, status, length] of [
      [undefined, 200, BIG],
      [{ headers: { range: `bytes=1-${BIG - 2}` } }, 206, BIG - 2],
    ] as const) {
      const bun = await read(await fetch(`${bunBase}/assets/big-9f8e7d.bin`, init))
      const nodeAnswer = await read(await fetch(`${nodeBase}/assets/big-9f8e7d.bin`, init))
      expect([bun.status, bun.headers["content-length"]]).toEqual([status, String(length)])
      expect(nodeAnswer).toEqual(bun)
    }
  })

  test("a current cached copy is a 304 on both", async () => {
    const init = { headers: { "if-modified-since": FUTURE } }
    const bun = await fetch(`${bunBase}/assets/page-1a2b3c.js`, init)
    const nodeAnswer = await fetch(`${nodeBase}/assets/page-1a2b3c.js`, init)
    expect([bun.status, nodeAnswer.status]).toEqual([304, 304])
    expect(nodeAnswer.headers.get("cache-control")).toBe(bun.headers.get("cache-control"))
    expect(await nodeAnswer.text()).toBe("")
  })

  test("nothing outside the tree, hidden inside it, or missing is served", async () => {
    for (const path of [
      "/assets/leak.js",
      "/assets/env.js",
      "/assets/.cache/x.js",
      "/assets/missing.js",
    ]) {
      const bun = await fetch(bunBase + path)
      const nodeAnswer = await fetch(nodeBase + path)
      expect([path, bun.status, nodeAnswer.status]).toEqual([path, 404, 404])
      for (const body of [await bun.text(), await nodeAnswer.text()]) {
        expect(body).not.toContain("outside")
        expect(body).not.toContain("SECRET")
      }
    }
  })

  test("the server bundle and unlisted root files reach the app, never the disk", async () => {
    for (const path of ["/server.js", "/.env", "/about"]) {
      expect(await (await fetch(bunBase + path)).text()).toBe(APP)
      expect(await (await fetch(nodeBase + path)).text()).toBe(APP)
    }
  })
})
